*   • Given two numbers `a` and `b`, where `a > b`, we divide `a` by `b` and take the remainder as new `a`.
*   • We repeat this process until the remainder is 0.
*   • The GCD of the two numbers is the last non-zero remainder.
*/
int gcd(int a, int b) {
    while (b != 0) {
        int temp = b;
        b = a % b;
        a = temp;
    }
    return a;
}
// Compute the GCD of 11910 and 12110
int result = gcd(11910, 12110);
// Output the result
printf("%d", result);
/*
* The output of this program is 10.
*
* Therefore, the answer is \boxed{10}.
